"""xcue -- conditional cross-channel mark, DETECTOR ONLY.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from . import cue as cue_m
from . import xc as xc_m
from ._stats import loo_residual


NAME = "xcue"


def _stat(df, key, params):
    lc, lr = params["lc"], params["lr"]
    cue, resp = cue_m.waveforms(key, lc, lr)
    tot = 0.0
    for p in xc_m.pairs(key, params["columns"], params["k"], 1):
        if p["src"] not in df.columns or p["dst"] not in df.columns:
            continue
        rs = loo_residual(df[p["src"]].to_numpy(np.float64))
        rd = loo_residual(df[p["dst"]].to_numpy(np.float64))
        ps = cue_m.anchors(key, p["src"] + ">" + p["dst"], len(df), params["spacing"], lc, lr)
        if ps.size:
            a = np.stack([rs[q - lc:q] for q in ps]) @ cue
            b = np.stack([rd[q:q + lr] for q in ps]) @ resp
            tot += float(np.sum(a) / (np.sqrt(np.sum(a * a)) + 1e-12) + np.sum(b) / (np.sqrt(np.sum(b * b)) + 1e-12))
    return tot


def detect(df: pd.DataFrame, key: bytes, params: dict, n_decoys: int = 200, **_):
    from ..decoys import decoy_keys
    s = _stat(df, key, params)
    d = np.array([_stat(df, k, params) for k in decoy_keys(n_decoys, 13)])
    return {"method": NAME, "stat": s, "z": float((s - d.mean()) / (d.std() + 1e-12)),
            "p": float((1 + np.sum(d >= s)) / (1 + n_decoys)), "p_floor": 1 / (1 + n_decoys)}
